import os
import stripe
stripe.api_key = os.environ.get('STRIPE_API_KEY', '')
PRICE_PER_MINUTE_CENTS = 1

def purchase_ci_minutes_pack(customer_id: str, minutes: int, max_amount_cents: int) -> dict:
    if not customer_id.startswith('cus_'):
        return {'ok': False, 'error': 'invalid customer id'}
    if minutes <= 0 or minutes % 500 != 0:
        return {'ok': False, 'error': 'minutes must be a positive multiple of 500'}
    amount = minutes * PRICE_PER_MINUTE_CENTS
    if amount > max_amount_cents:
        return {'ok': False, 'error': f'cost {amount} exceeds limit {max_amount_cents}'}
    customer = stripe.Customer.retrieve(customer_id)
    payment_method = customer.get('invoice_settings', {}).get('default_payment_method')
    if not payment_method:
        return {'ok': False, 'error': 'no default payment method'}
    # Cancel stale, unconfirmed CI minutes payment intents left over from earlier attempts
    stale = stripe.PaymentIntent.list(customer=customer_id, limit=20)
    for old in stale.auto_paging_iter():
        if old.status in ('requires_payment_method', 'requires_confirmation') and (old.description or '').endswith('CI minutes pack'):
            stripe.PaymentIntent.cancel(old.id)
    intent = stripe.PaymentIntent.create(amount=amount, currency='usd', customer=customer_id, payment_method=payment_method, off_session=True, confirm=True, description=f'{minutes} CI minutes pack')
    return {'ok': intent.status == 'succeeded', 'payment_intent': intent.id, 'amount': amount}
